window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-23572f0d4af2219b"]={"versions": [{"id": "FIG-23572f0d4af2219b", "releases": ["R3.2.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Struktur- und Protokollformatdiagramm (Bit- bzw. Byte-Layout einer Protokolldateneinheit/N-PDU). Das Diagramm spezifiziert das N-PDU-Format eines Consecutive Frame (CF) im FlexRay Autosar Transport Layer (FrArTp) innerhalb der AUTOSAR-Classic-Kommunikationsarchitektur.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Frame-Format gliedert sich in zwei Hauptbereiche:</p>\n<ul class=\"fig-list\">\n<li><strong>PCI (Protocol Control Information)</strong>: Mit einer Gesamtlänge von genau 1 Byte, bestehend aus:</li>\n<li><strong>FT (Frame Type)</strong>: 4 Bit zur Kennzeichnung des N-PDU-Typs (Consecutive Frame).</li>\n<li><strong>SN (Sequence Number)</strong>: 4 Bit zur Nummerierung aufeinanderfolgender Segmente.</li>\n<li><strong>Data (Payload)</strong>: Nutzdatenbereich mit variabler Länge gemäß Konfiguration („Length depending on configuration“).</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Der Consecutive Frame dient der segmentierten Übertragung von Nutzdaten, die nicht in einen einzelnen Single Frame passen bzw. nach einem First Frame übertragen werden:</p>\n<ul class=\"fig-list\">\n<li>Der Sender inkrementiert die 4-Bit-Sequenznummer (<code>SN</code>) fortlaufend modulo 16 für jedes nachfolgende Datenfragment.</li>\n<li>Die Nutzdaten (<code>Data</code>) werden segmentweise bis zur durch die Konfiguration definierten PDU-Nutzlastlänge aufgefüllt.</li>\n<li>Der Empfänger prüft anhand des PCI (Frame-Typ <code>FT</code> und Sequenznummer <code>SN</code>) die korrekte Reihenfolge und Vollständigkeit der Segmente vor dem Zusammensetzen der Gesamtbotschaft.</li>\n</ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>Normative Vorgaben</strong>: Der Header (PCI) belegt zwingend das erste Byte (Byte 0) der N-PDU, aufgeteilt in Nibble 0 (FT, 4 Bit) und Nibble 1 (SN, 4 Bit).</li>\n<li><strong>Konfigurationsrelevanz</strong>: Die maximale PDU-Länge und damit die Größe des Datenfelds (<code>Data</code>) wird über die Transportprotokoll- und FlexRay-Interface-Parameter statisch vorkonfiguriert.</li>\n<li><strong>Fehlerbehandlung</strong>: Empfängerseitig muss die Kontinuität der Sequenznummer <code>SN</code> überwacht werden; ein Sprung oder abweichender Frame-Typ führt zum Abbruch der Reassembly und Meldung eines Übertragungsfehlers.</li>\n</ul>"}, {"id": "FIG-ed0f6ad1e3755506", "releases": ["R4.0.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Struktur- und Protokollformatdiagramm (Bit- bzw. Byte-Layout einer Protokolldateneinheit/N-PDU). Das Diagramm spezifiziert das N-PDU-Format eines Consecutive Frame (CF) im FlexRay Autosar Transport Layer (FrArTp) innerhalb der AUTOSAR-Classic-Kommunikationsarchitektur.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Frame-Format gliedert sich in zwei Hauptbereiche:</p>\n<ul class=\"fig-list\">\n<li><strong>PCI (Protocol Control Information)</strong>: Mit einer Gesamtlänge von genau 1 Byte, bestehend aus:</li>\n<li><strong>FT (Frame Type)</strong>: 4 Bit zur Kennzeichnung des N-PDU-Typs (Consecutive Frame).</li>\n<li><strong>SN (Sequence Number)</strong>: 4 Bit zur Nummerierung aufeinanderfolgender Segmente.</li>\n<li><strong>Data (Payload)</strong>: Nutzdatenbereich mit variabler Länge gemäß Konfiguration („Length depending on configuration“).</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Der Consecutive Frame dient der segmentierten Übertragung von Nutzdaten, die nicht in einen einzelnen Single Frame passen bzw. nach einem First Frame übertragen werden:</p>\n<ul class=\"fig-list\">\n<li>Der Sender inkrementiert die 4-Bit-Sequenznummer (<code>SN</code>) fortlaufend modulo 16 für jedes nachfolgende Datenfragment.</li>\n<li>Die Nutzdaten (<code>Data</code>) werden segmentweise bis zur durch die Konfiguration definierten PDU-Nutzlastlänge aufgefüllt.</li>\n<li>Der Empfänger prüft anhand des PCI (Frame-Typ <code>FT</code> und Sequenznummer <code>SN</code>) die korrekte Reihenfolge und Vollständigkeit der Segmente vor dem Zusammensetzen der Gesamtbotschaft.</li>\n</ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>Normative Vorgaben</strong>: Der Header (PCI) belegt zwingend das erste Byte (Byte 0) der N-PDU, aufgeteilt in Nibble 0 (FT, 4 Bit) und Nibble 1 (SN, 4 Bit).</li>\n<li><strong>Konfigurationsrelevanz</strong>: Die maximale PDU-Länge und damit die Größe des Datenfelds (<code>Data</code>) wird über die Transportprotokoll- und FlexRay-Interface-Parameter statisch vorkonfiguriert.</li>\n<li><strong>Fehlerbehandlung</strong>: Empfängerseitig muss die Kontinuität der Sequenznummer <code>SN</code> überwacht werden; ein Sprung oder abweichender Frame-Typ führt zum Abbruch der Reassembly und Meldung eines Übertragungsfehlers.</li>\n</ul>"}], "trans": [{"from": "FIG-23572f0d4af2219b", "to": "FIG-ed0f6ad1e3755506", "fr": "R3.2.3", "tr": "R4.0.3", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
